	dur?: number;
	color?: string;
	style?: React.CSSProperties;
}> = ({text, t, start, stagger = 0.06, dur = 0.75, color, style}) => (
	<>
		{text.split(' ').map((w, i, arr) => (
			<React.Fragment key={i}>
				<Rise t={t} start={start + i * stagger} dur={dur} style={{color, ...style}}>
					{w}
				</Rise>
				{i < arr.length - 1 ? ' ' : null}
			</React.Fragment>
		))}
