				<div style={{marginTop: 16, textAlign: 'center', fontSize: 21, color: C.muted}}>
					3,000 emails/month free · no card
				</div>
			</div>
			{t > 3.0 ? <Cursor x={cx} y={cy} scale={1.25} press={press} /> : null}
		</AbsoluteFill>
	);
};

