					opacity: Math.min(1, card * 1.5) * (1 - tw(t, 5.0, 5.25)),
					transform: `translateY(${(1 - card) * 120}px)`,
				}}
			/>
			<div
				style={{
					position: 'absolute',
					left: rx,
					top: ry + (1 - card) * 120,
					width: rw,
					height: rh,
					background: C.card,
					border: `1.5px solid ${C.border}`,
					borderRadius: lerp(m, 18, 14),
