		const born = SPAWN0 + i * SPAWN_EVERY;
		if (t < born) return null;
		const yes = i % 3 !== 2;
		const pts = pathFor(yes);
		const p = along(pts, (t - born) * SPEED);
		return {i, yes, p, born};
	});

