		const n = NODES[idx];
		const w = n.w ?? NODE_W;
		let h = 0;
		for (const a of avatars) {
			if (!a || !a.p) continue;
			const [x, y] = a.p;
			if (x > n.x - 20 && x < n.x + w + 20 && Math.abs(y - n.y) < NODE_H / 2 + 10) h = 1;
		}
		return h;
	};

	const arrivals = (yes: boolean) =>
		avatars.filter((a) => a && a.yes === yes && !a.p).length;

