		const x0 = NODES[3].x + NODE_W;
		const x1 = to.x;
		const mx = (x0 + x1) / 2;
		return `M ${x0} ${ROW_Y} C ${mx} ${ROW_Y}, ${mx} ${to.y}, ${x1} ${to.y}`;
	};

