								{count}
							</div>
						) : null}
					</div>
				);
			})}

			{[4, 5].map((k) => {
				const yes = k === 4;
				const n = NODES[k];
				const p = sp(t, 1.05 + (yes ? 0 : 0.08));
				const x = (NODES[3].x + NODE_W + n.x) / 2;
				const y = (ROW_Y + n.y) / 2;
