			{t > 2.7 ? (
				<>
					{t > 4.6
						? [0, 1].map((i) => {
								const cyc = ((t - 4.6 + i * 0.9) % 1.8) / 1.8;
								return (
									<div
										key={`amb${i}`}
										style={{
											position: 'absolute',
											left: tileCx - TILE / 2,
											top: tileCy - TILE / 2,
											width: TILE,
											height: TILE,
											borderRadius: '24%',
											border: `2px solid ${C.flare}`,
											transform: `scale(${lerp(cyc, 1, 1.9)})`,
											opacity: (1 - cyc) * 0.22,
										}}
									/>
								);
							})
						: null}
					<div
						style={{
							position: 'absolute',
							left: tileCx - tileSize / 2,
							top: tileCy - tileSize / 2,
							transform: `scale(${tilePop}) rotate(${(1 - tilePop) * -30}deg)`,
							filter: 'drop-shadow(0 24px 40px rgba(255,51,0,0.3))',
						}}
					>
						<LumailTile size={tileSize} />
					</div>
				</>
			) : null}

			<div
				style={{
					position: 'absolute',
					left: LOCK_L + TILE + GAP,
					top: LOCK_Y - WORD * 0.54,
					clipPath: `inset(-20% ${(1 - word) * 100}% -20% 0)`,
					transform: `translateX(${(1 - word) * -60}px)`,
				}}
			>
				<Wordmark size={WORD} />
			</div>

			<div
				style={{
					position: 'absolute',
					left: 0,
					width: 1920,
					top: 505,
					textAlign: 'center',
					fontSize: 58,
					fontWeight: 500,
					letterSpacing: '-0.035em',
					color: C.ink,
				}}
			>
				{t > 3.6 ? (
					<>
						<Words text="The AI tool that will make you love" t={t} start={3.7} stagger={0.04} />{' '}
						<Words text="email marketing." t={t} start={4.0} stagger={0.05} color={C.flare} />
					</>
				) : null}
			</div>

			<div
				style={{
					position: 'absolute',
					left: 0,
					width: 1920,
					top: 640,
					display: 'flex',
					justifyContent: 'center',
					alignItems: 'center',
					gap: 40,
					opacity: Math.min(1, cta * 1.5),
					transform: `translateY(${(1 - cta) * 50}px)`,
				}}
			>
				<CTAButton label="Start free" fontSize={34} press={tw(t, 5.6, 5.68) * (1 - tw(t, 5.7, 5.9))} />
				<div style={{fontFamily: MONO, fontSize: 34, color: C.ink, position: 'relative'}}>
					lumail.io
					<div
						style={{
							position: 'absolute',
							left: 0,
							bottom: -6,
							height: 3,
							width: `${tw(t, 4.6, 5.1, E.inOut) * 100}%`,
							background: C.flare,
							borderRadius: 3,
						}}
					/>
				</div>
			</div>
			<div
				style={{
					position: 'absolute',
					left: 0,
					width: 1920,
					top: 770,
					textAlign: 'center',
					fontSize: 24,
					color: C.muted,
					opacity: small,
					transform: `translateY(${(1 - small) * 14}px)`,
				}}
			>
				3,000 emails/month free · no card · unlimited subscribers
			</div>
			<div
				style={{
					position: 'absolute',
					left: 0,
					width: 1920,
					top: 900,
					textAlign: 'center',
					fontFamily: MONO,
					fontSize: 19,
					letterSpacing: '0.2em',
					color: C.muted,
					opacity: tw(t, 5.0, 5.5),
				}}
			>
				RUNS INSIDE&nbsp;&nbsp;CHATGPT · CLAUDE · CURSOR · CODEX · HERMES · OPENCLAW
			</div>
		</AbsoluteFill>
	);
};

