	<svg width="22" height="18" viewBox="0 0 22 18">
		{[0, 1, 2, 3].map((i) => {
			const w = i % 2 ? 14 : 22;
			const x = align === 'l' ? 0 : align === 'c' ? (22 - w) / 2 : 22 - w;
