		lp: 0,
	}));
	const aps = [556, 441, 341, 225].map((d) => ({buf: new Float32Array(d + spread), i: 0}));
	const fb = 0.85;
	const damp = 0.25;
	for (let n = 0; n < N; n++) {
		const x = input[n] * 0.02;
		let y = 0;
		for (const c of combs) {
			const o = c.buf[c.i];
			c.lp = o * (1 - damp) + c.lp * damp;
			c.buf[c.i] = x + c.lp * fb;
			c.i = (c.i + 1) % c.buf.length;
			y += o;
		}
		for (const a of aps) {
			const o = a.buf[a.i];
			a.buf[a.i] = y + o * 0.5;
			a.i = (a.i + 1) % a.buf.length;
			y = o - y;
		}
		out[n] = y;
	}
	return out;
};
