		const am = Math.abs(Math.sin(TAU * 7.5 * t + Math.sin(TAU * 1.3 * t) * 2)) ** 2;
		const env = clamp(t / 0.05) * clamp((dur - t) / 0.08);
		put(fx, i0 + k, bp.run(noise()) * am * env * g, 0.1);
