		const t = k / SR;
		let env = Math.exp(-t * 16) * 0.55;
		for (const d of [0, 0.012, 0.024]) if (t >= d) env += Math.exp(-(t - d) * 160);
		const v = bp.run(noise()) * env * g * 0.55;
		put(fx, i0 + k, v, 0.05, 0.35);
	}
};

