	const i0 = Math.round(t0 * SR);
	const hp = new Biquad('hp', 7500, 0.8);
	const len = (open ? 0.35 : 0.08) * SR;
	const pan = (rnd() - 0.5) * 0.5;
	for (let k = 0; k < len; k++) {
		const t = k / SR;
		const v = hp.run(noise()) * Math.exp(-t * (open ? 12 : 65)) * g * 0.3;
		put(fx, i0 + k, v, pan, 0.05);
	}
};

